import 'package:flutter/material.dart';
class SpecialtySectionHeader extends StatelessWidget { final String title; final Color accentColor; final VoidCallback? onSeeAll; const SpecialtySectionHeader({super.key,required this.title,required this.accentColor,this.onSeeAll}); @override Widget build(BuildContext context){return Row(children:[Container(width:4,height:22,decoration:BoxDecoration(color:accentColor,borderRadius:BorderRadius.circular(4))),const SizedBox(width:8),Expanded(child:Text(title,style:const TextStyle(fontSize:17,fontWeight:FontWeight.w800))),if(onSeeAll!=null)TextButton(onPressed:onSeeAll,child:Text('عرض الكل',style:TextStyle(color:accentColor,fontWeight:FontWeight.w700))) ]);}}
